import {Chart} from "react-google-charts";
import {Paper, Stack} from "@mui/material";
import history from "../../dataImport/history.json";

//// Year-over-year line charts for a school or district, built from dataImport/history.json
//// (generated by scripts/build-history.mjs).

// same blue / red as the bar charts; the state orange is a step darker so a thin line stays readable
const OWN_COLOR = "#3366cc";
const DISTRICT_COLOR = "#dc3911";
const STATE_COLOR = "#e08600";

const PERCENT = {suffix: "%", fractionDigits: 1};
const METRICS = [
    {id: "positiveMathScoreAvg_E", title: "Positive Math Score (Elem. & Middle)", format: PERCENT},
    {id: "positiveReadingScoreAvg_E", title: "Positive Reading Score (Elem. & Middle)", format: PERCENT},
    {id: "positiveMathScoreAvg_H", title: "Positive Math Score (High School)", format: PERCENT},
    {id: "positiveReadingScoreAvg_H", title: "Positive Reading Score (High School)", format: PERCENT},
    {id: "gradRate", title: "On-time Graduation Rate", format: PERCENT},
    {id: "ACTCompositeAVG", title: "Average ACT Score", format: {fractionDigits: 1}},
    {id: "avgTeacherSalary", title: "Average Teacher Pay", format: {prefix: "$", fractionDigits: 0}, axisFormat: "$#,###"},
    {id: "teacherReturnRate", title: "3-Year Teacher Retention", format: PERCENT},
    {id: "studentsInPovertyPct", title: "Students in Poverty", format: PERCENT},
    {id: "chronicAbsenteeismRate", title: "Chronic Absenteeism", format: PERCENT},
    // enrollment is shown on its own: a school's count cannot share an axis with the state's
    {id: "totalStudents", title: "Enrollment", format: {fractionDigits: 0}, axisFormat: "#,###", ownOnly: true},
];

const hasValues = (values) => values !== undefined && values.some((value) => value !== null);

const trendChart = (metric, series) => {
    const data = [
        ["Year", ...series.map((entry) => entry.label)],
        ...history.years.map((year, index) => [String(year), ...series.map((entry) => entry.values[index])]),
    ];
    const options = {
        title: metric.title,
        titleTextStyle: {fontSize: 14, bold: false},
        legend: "none",
        width: 300,
        height: 250,
        lineWidth: 2,
        pointSize: 7,
        colors: series.map((entry) => entry.color),
        series: Object.fromEntries(series.map((entry, index) => [index, entry.dashed ? {lineDashStyle: [5, 4]} : {}])),
        chartArea: {left: 60, right: 15, top: 45, bottom: 35},
        hAxis: {textStyle: {fontSize: 12}},
        vAxis: {textStyle: {fontSize: 12}, format: metric.axisFormat, gridlines: {color: "#e6e6e6"}, minorGridlines: {count: 0}},
        focusTarget: "category", // one tooltip listing every line for the hovered year
    };
    return (
        <Chart
            key={metric.id}
            chartType="LineChart"
            width="300px"
            height="250px"
            data={data}
            options={options}
            formatters={series.map((entry, index) => ({type: "NumberFormat", column: index + 1, options: metric.format}))}
        />
    )
};

const legendSwatch = (color, dashed) => ({
    display: "inline-block",
    width: "26px",
    borderTop: `3px ${dashed ? "dashed" : "solid"} ${color}`,
    marginRight: "6px",
    verticalAlign: "middle",
});

const Trends = ({record}) => {
    const own = history.records[record.schoolId];
    if (own === undefined) return null;
    const isDistrict = record.schoolCode === "D";
    const district = isDistrict ? undefined : history.records[record.districtId];

    const charts = METRICS.filter((metric) => hasValues(own[metric.id])).map((metric) => {
        const series = [{label: record.schoolName, values: own[metric.id], color: OWN_COLOR}];
        if (!metric.ownOnly) {
            if (hasValues(district?.[metric.id])) {
                series.push({label: "District", values: district[metric.id], color: DISTRICT_COLOR});
            }
            if (hasValues(history.state[metric.id])) {
                series.push({label: "State", values: history.state[metric.id], color: STATE_COLOR, dashed: true});
            }
        }
        return trendChart(metric, series);
    });
    if (charts.length === 0) return null;

    const firstYear = history.years[0];
    const lastYear = history.years[history.years.length - 1];
    return (
        <Paper elevation={12} sx={{marginTop: "10px", border: '1px solid black'}}>
            <Stack>
                <h5 className={"chart-title"} style={{marginLeft: "100px", marginTop: "10px"}}>
                    Trends, {firstYear}&ndash;{lastYear}
                </h5>
                <div style={{textAlign: "center", fontSize: "small", fontWeight: "bold", padding: "10px"}}>
                    <span style={{marginRight: "24px"}}><span style={legendSwatch(OWN_COLOR)}/>{record.schoolName}</span>
                    {isDistrict ? <></> : <span style={{marginRight: "24px"}}><span style={legendSwatch(DISTRICT_COLOR)}/>District</span>}
                    <span><span style={legendSwatch(STATE_COLOR, true)}/>State</span>
                </div>
                <Stack
                    className="chart-container"
                    direction="row"
                    justifyContent="space-evenly"
                    alignItems="center"
                    flexWrap="wrap"
                >
                    {charts}
                </Stack>
                <div style={{textAlign: "center", fontSize: "small", color: "#666", padding: "0 20px 12px"}}>
                    A gap means the value was not reported that year. Hover a chart for exact figures.
                </div>
            </Stack>
        </Paper>
    )
};

export default Trends
